require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('hospital');$hospital=current_hospital($user);if(!$hospital){http_response_code(403);exit('No active hospital assigned.');}
if(request_method('POST')&&($_POST['action']??'')==='inventory'){Csrf::verify();$group=$_POST['blood_group']??'';$units=(int)($_POST['units_available']??-1);if(in_array($group,blood_groups(),true)&&$units>=0&&$units<=10000){db()->prepare('INSERT INTO blood_inventory(hospital_id,blood_group,units_available) VALUES(?,?,?) ON DUPLICATE KEY UPDATE units_available=VALUES(units_available)')->execute([(int)$hospital['id'],$group,$units]);audit('inventory_updated','hospital',(int)$hospital['id'],['blood_group'=>$group,'units'=>$units]);flash('success','Prototype inventory quantity updated.');redirect('hospital/inventory.php');}}
$inv=db()->prepare('SELECT * FROM blood_inventory WHERE hospital_id=? ORDER BY FIELD(blood_group,\'A+\',\'A-\',\'B+\',\'B-\',\'AB+\',\'AB-\',\'O+\',\'O-\')');$inv->execute([(int)$hospital['id']]);$inventory=[];foreach($inv->fetchAll() as $r)$inventory[$r['blood_group']]=$r;
$incoming=db()->prepare("SELECT t.*,h.name requester_name FROM blood_transfer_requests t JOIN hospitals h ON h.id=t.to_hospital_id WHERE t.from_hospital_id=? ORDER BY t.created_at DESC LIMIT 40");$incoming->execute([(int)$hospital['id']]);$incomingRows=$incoming->fetchAll();$outgoing=db()->prepare("SELECT t.*,h.name supplier_name FROM blood_transfer_requests t JOIN hospitals h ON h.id=t.from_hospital_id WHERE t.to_hospital_id=? ORDER BY t.created_at DESC LIMIT 40");$outgoing->execute([(int)$hospital['id']]);$outgoingRows=$outgoing->fetchAll();$pageTitle='Inventory & Transfers';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Prototype resource coordination</div><h1>Blood inventory & transfers</h1><p class="page-note">Inventory values are demonstration records only and must not be treated as validated blood-bank stock.</p></div><a class="btn" href="<?=e(url('hospital/transfer-create.php'))?>">Request Transfer</a></div><?=hospital_nav($user)?><div class="grid-2"><div class="card"><h2>Update local inventory</h2><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="inventory"><div class="form-grid"><div class="field"><label>Blood group</label><select name="blood_group"><?php foreach(blood_groups() as $g):?><option><?=e($g)?></option><?php endforeach;?></select></div><div class="field"><label>Units available</label><input type="number" min="0" max="10000" name="units_available" required></div></div><button class="btn">Save Quantity</button></form></div><div class="card"><h2>Current prototype stock</h2><div class="grid-2"><?php foreach(blood_groups() as $g):?><div class="metric"><span><?=e($g)?></span><strong><?=e((string)($inventory[$g]['units_available']??0))?></strong></div><?php endforeach;?></div></div></div><h2 class="mt-2">Requests for your hospital's stock</h2><div class="table-wrap"><table class="table"><thead><tr><th>Requester</th><th>Blood</th><th>Units</th><th>Urgency</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$incomingRows):?><tr><td colspan="6" class="empty">No incoming transfer requests.</td></tr><?php endif;?><?php foreach($incomingRows as $t):?><tr><td><?=e($t['requester_name'])?></td><td><?=e($t['blood_group'])?></td><td><?=e((string)$t['units_requested'])?></td><td><?=e($t['urgency'])?></td><td><span class="badge <?=$t['status']==='accepted'?'green':($t['status']==='declined'?'red':'amber')?>"><?=e($t['status'])?></span></td><td><?php if($t['status']==='pending'):?><form method="post" action="<?=e(url('hospital/transfer-action.php'))?>" class="mini-actions"><?=Csrf::field()?><input type="hidden" name="id" value="<?=e((string)$t['id'])?>"><button class="btn btn-success btn-sm" name="action" value="accept">Accept</button><button class="btn btn-outline btn-sm" name="action" value="decline">Decline</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><h2 class="mt-2">Transfers requested by your hospital</h2><div class="table-wrap"><table class="table"><thead><tr><th>Supplier</th><th>Blood</th><th>Units</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$outgoingRows):?><tr><td colspan="5" class="empty">No outgoing transfer requests.</td></tr><?php endif;?><?php foreach($outgoingRows as $t):?><tr><td><?=e($t['supplier_name'])?></td><td><?=e($t['blood_group'])?></td><td><?=e((string)$t['units_requested'])?></td><td><span class="badge <?=$t['status']==='completed'?'green':($t['status']==='declined'?'red':'amber')?>"><?=e($t['status'])?></span></td><td><div class="mini-actions"><?php if($t['status']==='accepted'):?><form method="post" action="<?=e(url('hospital/transfer-complete.php'))?>"><?=Csrf::field()?><input type="hidden" name="id" value="<?=e((string)$t['id'])?>"><button class="btn btn-success btn-sm">Confirm Receipt</button></form><?php elseif($t['status']==='pending'):?><form method="post" action="<?=e(url('hospital/transfer-cancel.php'))?>"><?=Csrf::field()?><input type="hidden" name="id" value="<?=e((string)$t['id'])?>"><button class="btn btn-outline btn-sm">Cancel</button></form><?php else:?>—<?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div></section>
<?php require dirname(dirname(__DIR__)).'/src/templates/footer.php';?>
